const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year2002_start = '2002-01-01';
  const year2002_end = '2002-12-31';
  const year2022_start = '2022-01-01';
  const year2022_end = '2022-12-31';

  // Global region to reduce over. This relies on the dataset already masking land.
  const globalRegion = ee.Geometry.Rectangle([-180, -90, 180, 90]);

  // 2. Data Acquisition & Check
  const collectionId = 'MODIS/051/L3SMI_CHL'; // MODIS Aqua Chlorophyll a concentration
  const bandName = 'chlor_a';

  let col2002 = ee.ImageCollection(collectionId)
    .filterDate(year2002_start, year2002_end)
    .select(bandName);

  let col2022 = ee.ImageCollection(collectionId)
    .filterDate(year2022_start, year2022_end)
    .select(bandName);

  const size2002 = await col2002.size().getInfo();
  const size2022 = await col2022.size().getInfo();

  if (size2002 === 0 || size2022 === 0) {
    console.log(`2002 Images: ${size2002}, 2022 Images: ${size2022}`);
    console.log("C1: Empty Collection (No images found for one or both comparison points).");
    return;
  }

  // 3. Processing
  // Take the mean of chlorophyll-a for each year to get an annual average image.
  const img2002 = col2002.mean();
  const img2022 = col2022.mean();

  const scale = 4000; // ~4km resolution for MODIS L3SMI data.
  const maxPixels = 1e13; // Sufficiently large for global reduction.

  // Reduce region to get the global mean chlorophyll-a for each year.
  const meanChl2002 = await img2002.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: globalRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get(bandName).getInfo();

  const meanChl2022 = await img2022.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: globalRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get(bandName).getInfo();

  // 4. Calculation & Validation
  if (meanChl2002 === null || isNaN(meanChl2002) || meanChl2022 === null || isNaN(meanChl2022)) {
    console.log(`2002 Mean Chl: ${meanChl2002}, 2022 Mean Chl: ${meanChl2022}`);
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  // A "greener hue" implies an increase in chlorophyll-a concentration.
  const increase = meanChl2022 > meanChl2002;

  console.log(`2002 Global Mean Chlorophyll-a: ${meanChl2002.toFixed(4)} mg/m^3`);
  console.log(`2022 Global Mean Chlorophyll-a: ${meanChl2022.toFixed(4)} mg/m^3`);
  console.log(`Change: ${(meanChl2022 - meanChl2002).toFixed(4)} mg/m^3`);

  if (increase) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
